from pathlib import Path
import base64,json,html
R=Path(__file__).resolve().parents[1];O=R/'simulator';D=R/'tools/assembly_illustrations'
def image(name,caption):
 data=base64.b64encode((D/(name+'.png')).read_bytes()).decode()
 return f'<figure class="zoomable"><img alt="{html.escape(caption)}" src="data:image/png;base64,{data}" loading="lazy"><figcaption>{caption}</figcaption></figure>'
def svg(body,caption,w=900,h=430):
 return f'<figure class="zoomable"><svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 {w} {h}" role="img" aria-label="{html.escape(caption)}"><defs><marker id="a" markerWidth="8" markerHeight="8" refX="7" refY="4" orient="auto"><path d="M0 0L8 4L0 8" fill="#526b80"/></marker></defs><rect width="100%" height="100%" fill="#f8fafc"/>{body}</svg><figcaption>{caption}</figcaption></figure>'
def t(x,y,text,size=20,fill='#18364b',anchor='start'):
 return f'<text x="{x}" y="{y}" text-anchor="{anchor}" fill="{fill}" font-size="{size}" font-family="Arial, sans-serif">{html.escape(text)}</text>'
def rect(x,y,w,h,color='#e4eef7',stroke='#9bb0c1',r=10):return f'<rect x="{x}" y="{y}" width="{w}" height="{h}" rx="{r}" fill="{color}" stroke="{stroke}" stroke-width="2"/>'
def line(x,y,X,Y,color='#526b80',arrow=False):return f'<path d="M{x} {y} L{X} {Y}" fill="none" stroke="{color}" stroke-width="3"'+(' marker-end="url(#a)"' if arrow else '')+'/>'
def check(text):return '<label class="check"><input type="checkbox">'+text+'</label>'
def note(text):return '<p class="note">'+text+'</p>'
def step(n,title,body):return f'<section class="step" id="s{n}"><div class="step-title"><span>{n:02}</span><h2>{title}</h2></div>{body}</section>'
def table(headers,rows):return '<div class="table"><table><thead><tr>'+''.join('<th>'+x+'</th>' for x in headers)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+str(c)+'</td>' for c in row)+'</tr>' for row in rows)+'</tbody></table></div>'
